Page._content:
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=Noto+Sans+SC:wght@400;700&display=swap');

:root {
  --primary-color: #ff9500;
  --secondary-color: #34c759;
  --accent-color: #ff3b30;
  --bg-color: #1a1a1a;
  --text-color: #cccccc;
  --heading-color: #ffffff;
}

body {
  font-family: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
  background: #1a1a1a;
  color: var(--text-color);
  min-height: 100vh;
}

header {
  background: #0d0d0d !important;
  border-bottom: 2px solid var(--primary-color);
}

header .logo {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 1.5em;
  color: var(--primary-color) !important;
  letter-spacing: 2px;
}

#nav-menu a {
  color: var(--text-color) !important;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.9em;
  transition: all 0.2s ease;
}

#nav-menu a:hover {
  color: var(--primary-color) !important;
}

#main-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 2em;
  color: var(--primary-color);
  text-transform: uppercase;
  letter-spacing: 4px;
}

#sidebar {
  background: #151515;
  border-left: 1px solid #333;
}

.widget {
  background: #1e1e1e;
  border: 1px solid #333;
}

.widget-title {
  font-family: 'JetBrains Mono', monospace;
  color: var(--primary-color);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.post {
  background: #1e1e1e;
  border: 1px solid #333;
  padding: 20px;
  margin-bottom: 25px;
}

.post:hover {
  border-color: var(--primary-color);
}

.post-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 1.5em;
  color: var(--heading-color);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.post-title a {
  color: var(--heading-color) !important;
}

.post-title a:hover {
  color: var(--primary-color) !important;
}

.post-meta {
  color: #666;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.8em;
}

.post-content {
  line-height: 1.8;
}

.post-content h1, .post-content h2, .post-content h3 {
  color: var(--heading-color);
  font-family: 'JetBrains Mono', monospace;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.post-content code {
  background: #2d2d2d;
  color: var(--primary-color);
  padding: 2px 6px;
  font-family: 'JetBrains Mono', monospace;
}

.post-content pre {
  background: #0d0d0d;
  border: 1px solid #333;
}

.post-content pre code {
  background: none;
  color: #aaa;
}

blockquote {
  background: #151515;
  border-left: 3px solid var(--primary-color);
  padding: 12px 15px;
}

blockquote p {
  margin: 0;
  color: var(--text-color);
  font-style: italic;
}

table {
  border-collapse: collapse;
  width: 100%;
}

table th, table td {
  border: 1px solid #333;
  padding: 10px;
}

table th {
  background: #1a1a1a;
  color: var(--primary-color);
  font-family: 'JetBrains Mono', monospace;
}

footer {
  background: #0d0d0d !important;
  border-top: 2px solid var(--primary-color);
  padding: 15px;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.8em;
}

footer a {
  color: var(--primary-color) !important;
}

::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #1a1a1a;
}

::-webkit-scrollbar-thumb {
  background: var(--primary-color);
}

@media (max-width: 768px) {
  #main-title {
    font-size: 1.5em;
  }
}

